cd /home/imnyj/Workspace/paper4/coder/runs && /home/imnyj/venv/bin/python - <<'EOF'
import re, collections
for arm in ['mean_seed42','accumulate_seed42']:
    cur=None; cnt=collections.Counter(); eps=collections.defaultdict(list)
    for line in open(f'{arm}/sup/train.log', errors='replace'):
        m=re.search(r'Starting training for ([\w\-]+)', line)
        if m: cur=m.group(1)
        if 'ZERO gradient updates' in line:
            e=re.search(r'Episode (\d+)', line)
            cnt[cur]+=1; eps[cur].append(int(e.group(1)) if e else -1)
    print(f'--- {arm}: total {sum(cnt.values())} ---')
    for k,v in cnt.items():
        ee=sorted(eps[k]); print(f'  {k:12s} {v:3d}건  에피소드 {ee[0]}~{ee[-1]}')
    print('  전체 경고 예시:', end=' ')
    for line in open(f'{arm}/sup/train.log', errors='replace'):
        if 'ZERO gradient updates' in line:
            print(line.strip()[:170]); break
EOF

